import { Component, EventEmitter, Input, OnChanges, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { MatMenuModule } from '@angular/material/menu';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { FormsModule } from "@angular/forms";
import { MatSlideToggleModule } from '@angular/material/slide-toggle';
import { MatTooltipModule } from "@angular/material/tooltip";
import { TranslateModule, TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'rt-tool-options',
  standalone: true,
  imports: [IconComponent, MatMenuModule, FormsModule, MatSlideToggleModule, MatTooltipModule, TranslateModule],
  templateUrl: './rt-tool-options.component.html',
  styleUrl: './rt-tool-options.component.scss'
})
export class RtToolOptionsComponent implements OnChanges {

  zoomexpand: boolean = false;
  zoom: any = [];

  @Output() demoToggled = new EventEmitter<void>();
  @Output() exportTranscript = new EventEmitter<void>();
  @Input() visibleIssueModelChange: EventEmitter<boolean>;
  @Input() showTimestampChange: EventEmitter<boolean>;
  @Input() isDisable: boolean;
  @Input() isSessionLive: boolean;
  @Input() showTimestamp: boolean;
  @Input() compareEnabled: boolean;
  @Input() zoomLevel: number;
  @Input() zoomLevelChange: EventEmitter<number>;

  @Input() fullViewMode: boolean;
  @Input() fullViewModeChange: EventEmitter<boolean>;

  zoomLable: string = 'Actual';

  @Input() indexEnabled: boolean;
  @Input() indexEnabledChange: EventEmitter<boolean>;

  @Input() visibleMarkNavModel: boolean;
  @Input() visibleMarkNavModelChange: EventEmitter<boolean>;

  @Input() isTranscViewer: boolean;

  // When true, render a reduced set of menu items (Zoom submenu + Time Stamp
  // only). Used by the individual-doc compare view of a transcript to show a
  // compact kebab. Leave false everywhere else — full menu renders.
  @Input() limitedActions: boolean = false;

  constructor(private readonly tost: TostbarService, private readonly translate: TranslateService) { 
    this.translate.onLangChange.subscribe(() => {
      this.updateZoomLabels();
    });
    this.updateZoomLabels();
  }

  updateZoomLabels() {
    if (this.zoomLevel === 1.2) {
      this.zoomLable = this.translate.instant('rt.toolOptions.fitHeight');
    } else if (this.zoomLevel === 1) {
      this.zoomLable = this.translate.instant('rt.toolOptions.actual');
    } else {
      this.zoomLable = (this.zoomLevel * 100).toFixed(0) + '%';
    }
    this.zoom = [
      { name: 1, text: this.translate.instant('rt.toolOptions.actual') },
      { name: 1.2, text: this.translate.instant('rt.toolOptions.fitHeight') }
    ];
  }

  openissuemanager() {
    if (this.indexEnabled) {
      this.indexEnabled = false;
      this.indexEnabledChange.emit(this.indexEnabled);
    }
    if (this.visibleMarkNavModel) {
      this.visibleMarkNavModel = false;
      this.visibleMarkNavModelChange.emit(this.visibleMarkNavModel);
    }

    this.visibleIssueModelChange.emit(true);
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['zoomLevel']) {
      if (this.zoomLevel == 1) {
        this.zoomLable = this.translate.instant('rt.toolOptions.actual');
      } else if (this.zoomLevel == 1.2) {
        this.zoomLable = this.translate.instant('rt.toolOptions.fitHeight');
      } else {
        this.zoomLable = (this.zoomLevel * 100).toFixed(0) + '%'
      }
    }
  }

  handleZoomExpand() {
    if (this.isDisable) return;
    this.zoomexpand = !this.zoomexpand
  }

  toggleTimeStamp() {
    if (this.isDisable) return;
    this.showTimestampChange.emit(this.showTimestamp)
  }

  changeZoom(flag: 'I' | 'O') {
    const cr_zoom = Math.round(this.zoomLevel * 10) / 10;
    const val = flag == 'I' ? (cr_zoom + 0.1) : (cr_zoom - 0.1);
    this.changeZoomValue(Math.round(val * 10) / 10);
  }

  changeZoomValue(v: number) {
    if (0 >= v || v > 1.8) return;
    this.zoomLevel = v;
    this.zoomLevelChange.emit(this.zoomLevel);
  }

  changeZoomValueByInput(e: Event) {
    const v = (e.target as HTMLInputElement).value;
    if (!v) return;
    const num = Number.parseFloat(v);
    if (Number.isNaN(num) || num < 10 || num > 180) {
      return;
    }
    this.changeZoomValue(num / 100);
  }

  toggleFullViewMode() {
    if (this.isDisable) return;
    this.fullViewMode = !this.fullViewMode;
    this.fullViewModeChange.emit(this.fullViewMode)
  }

  onZoomInput(event: Event) {
    const input = event.target as HTMLInputElement;
    const value = Number.parseFloat(input.value);

    if (!Number.isNaN(value) && value > 180) {
      input.value = '180';
    }
    if (!Number.isNaN(value) && value < 0) {
      input.value = '10';
    }
  }

  onExportTranscript() {
    if (this.isDisable) return;
    this.exportTranscript.emit();
  }

  runDemo() {
    if (this.isSessionLive) return;
    this.demoToggled.emit();
  }
}
