import { CdkDrag } from '@angular/cdk/drag-drop';
import { Component, OnInit } from '@angular/core';
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { SearchService } from '../../../../search/search.service';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { SearchResultComponent } from '../search-result/search-result.component';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'rt-search-box',
  standalone: true,
  imports: [CdkDrag, IconComponent, MatCheckboxModule, FormsModule, ButtonComponent, SearchResultComponent, TranslateModule],
  templateUrl: './rt-search-box.component.html',
  styleUrl: './rt-search-box.component.scss'
})
export class RtSearchBoxComponent implements OnInit {

  searchTerm: string = '';
  menustate: string = 'O';
  wholeWord: boolean = false;

  isSearching: boolean = false;
  isInputFocused: boolean = false;

  showresult: boolean = false;

  constructor(private readonly searchService: SearchService, private readonly fds: FeedDisplayService) { }

  clearsearch() {
    this.searchTerm = '';
    this.search();
  }

  ngOnInit(): void {
    if (this.searchService.searchTerm) {
      this.searchTerm = this.searchService.searchTerm;
      this.showresult = true;
    }
  }

  search() {
    if (this.searchTerm == '') {
      this.searchService.searchTerm = null
      this.searchService.matches$.next([]);
      return;
    }
    const data = this.fds.getActiveFeedData();
    this.isSearching = true;
    this.searchService.search(this.searchTerm, data, this.wholeWord, false);
    this.showresult = true;
    this.isSearching = false;
    this.showresult = true;

    // Activate mini split view if session is live (same as scroll-up behavior)
    if ((this.fds.sessionDetail?.cStatus === 'R' || this.fds.demoStream) && !this.fds.pausedState) {
      this.fds.pauseEvent();
    }
  }

  get totalMatches() {
    return this.searchService.matches$.value.length;
  }

  get currentMatch() {
    return this.searchService.currentMatch$.value + 1;
  }

  get currentPage() {
    const currentMatch = this.searchService.getCurrentMatch();
    return currentMatch ? currentMatch.page + 1 : 1;
  }

  onNext() {
    this.searchService.nextMatch();
    if ((this.fds.sessionDetail?.cStatus === 'R' || this.fds.demoStream) && !this.fds.pausedState) {
      this.fds.pauseEvent();
    }
  }

  onPrevious() {
    this.searchService.previousMatch();
    if ((this.fds.sessionDetail?.cStatus === 'R' || this.fds.demoStream) && !this.fds.pausedState) {
      this.fds.pauseEvent();
    }
  }
}
