import { Injectable } from '@angular/core';

import { BehaviorSubject } from 'rxjs';
import { feeds } from '../interfaces/feed.interface';


export interface SearchMatch {
  page: number;     // 0-based page index
  line: number;     // 0-based line index within page
  start: number;    // start char index within joined line string
  end: number;      // end (exclusive)
  lineText: string;
  matchIndex?:number;
}



@Injectable()
export class SearchService {
  public searchTerm = '';
  public indexTerm = '';
  public matches: SearchMatch[] = [];
  public currentMatchIndex = 0;
  public curMatch: SearchMatch | null = null;

  matches$ = new BehaviorSubject<SearchMatch[]>([]);
  currentMatch$ = new BehaviorSubject<number>(0);
  searchingData = false;
  iswholeWord = false;

  constructor() { }

  /**
   * Escape user input to be used in a literal RegExp.
   */
  private escapeRegExp(s: string): string {
    // Escapes: - \ ^ $ * + ? . ( ) | { } [ ]
    return s.replace(/[\\^$*+?.()|[\]{}-]/g, '\\$&');
  }

  /**
   * Build a Unicode-aware regex based on options.
   * - wholeWord: only applied if term is a single "word" (letters/numbers/_).
   * - matchCase: adds 'i' if false.
   */
  private buildRegex(term: string, wholeWord: boolean, matchCase: boolean): RegExp | null {
    const trimmed = term?.trim();
    if (!trimmed) return null;

    const escaped = this.escapeRegExp(trimmed);
    const flags = `gu${matchCase ? '' : 'i'}`; // global + unicode (+ case-insensitive when needed)

    // Apply whole-word only if the term itself is a single "word"
    // Use Unicode property escapes for word characters.
    const isWord = /^[\p{L}\p{N}_]+$/u.test(trimmed);

    const pattern = (wholeWord && isWord)
      ? `(?<![\\p{L}\\p{N}_])${escaped}(?![\\p{L}\\p{N}_])`
      : escaped;

    return new RegExp(pattern, flags);
  }

  /**
   * Run the search over your pagewise data.
   * @param term      The query string.
   * @param data      Array of pages (feeds[]).
   * @param wholeWord Whole word toggle.
   * @param matchCase Case sensitive toggle.
   */
  search(term: string, data: feeds[], wholeWord: boolean, matchCase: boolean) {
    this.iswholeWord = wholeWord;
    this.searchingData = true;

    // Prepare regex
    const regex = this.buildRegex(term, wholeWord, matchCase);
    this.searchTerm = term ?? '';

    // Early exit on empty / invalid regex
    if (!regex || !Array.isArray(data) || data.length == 0) {
      this.matches = [];
      this.matches$.next(this.matches);
      this.currentMatchIndex = 0;
      this.currentMatch$.next(this.currentMatchIndex);
      this.curMatch = null;
      this.searchingData = false;
      return;
    }

    const out: SearchMatch[] = [];

    // Scan pages/lines
    for (let pageIndex = 0; pageIndex < data.length; pageIndex++) {
      const page = data[pageIndex];
      const lines = page?.data ?? [];
      for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {
        const joined = (lines[lineIndex].lines ?? []).join(' ');
        if (!joined) continue;

        // IMPORTANT: reset lastIndex for each new string when using /g/
        regex.lastIndex = 0;

        let m: RegExpExecArray | null;
        while ((m = regex.exec(joined)) !== null) {
          // Guard against zero-length matches (shouldn't happen here, but safe)
          const start = m.index;
          const len = m[0]?.length ?? 0;
          if (len == 0) {
            // Avoid infinite loop on zero-length matches
            regex.lastIndex = start + 1;
            continue;
          }
          out.push({ page: pageIndex, line: lineIndex, start, end: start + len, lineText: joined });
        }
      }
    }

    // Publish results
    this.matches = out;
    this.matches$.next(this.matches);

    this.currentMatchIndex = 0;
    this.curMatch = this.matches[0] ?? null;
    this.currentMatch$.next(this.currentMatchIndex);

    this.searchingData = false;
  }

  nextMatch() {
    if (!this.matches.length) return;
    this.currentMatchIndex = (this.currentMatchIndex + 1) % this.matches.length;
    this.curMatch = this.matches[this.currentMatchIndex];
    this.currentMatch$.next(this.currentMatchIndex);
  }


  toMatch(index) {
    if (!this.matches.length) return;
    this.currentMatchIndex = (index) % this.matches.length;
    this.curMatch = this.matches[this.currentMatchIndex];
    this.currentMatch$.next(this.currentMatchIndex);
  }


  previousMatch() {
    if (!this.matches.length) return;
    this.currentMatchIndex = (this.currentMatchIndex - 1 + this.matches.length) % this.matches.length;
    this.curMatch = this.matches[this.currentMatchIndex];
    this.currentMatch$.next(this.currentMatchIndex);
  }

  getCurrentMatch(): SearchMatch | null {
    if (!this.matches.length) return null;
    return this.matches[this.currentMatchIndex] ?? null;
  }

  isCurrentMatch(lineIndex: number, pageIndex: number): SearchMatch | false {
    const m = this.getCurrentMatch();
    if (m && m.page == (pageIndex - 1) && m.line == (lineIndex - 1)) return m;
    return false;
  }

  getCurrentMatchPosition(): number {
    const m = this.getCurrentMatch();
    return m ? m.start : -1;
  }

  getCurrentMatchLength(): number {
    const m = this.getCurrentMatch();
    return m ? (m.end - m.start) : 0;
  }

  get highlightTerm(): string {
    return this.searchTerm || this.indexTerm;
  }

  indexSearch(term: string, data: feeds[], wholeWord: boolean, matchCase: boolean) {
    this.indexTerm = term ?? '';
    const savedSearchTerm = this.searchTerm;
    this.search(term, data, wholeWord, matchCase);
    this.searchTerm = savedSearchTerm;
  }

  clearIndex() {
    this.indexTerm = '';
    this.matches = [];
    this.curMatch = null;
    this.currentMatchIndex = 0;
    this.matches$.next([]);
    this.currentMatch$.next(0);
  }

  clear() {
    this.searchTerm = '';
    this.indexTerm = '';
    this.matches = [];
    this.curMatch = null;
    this.currentMatchIndex = 0;
    this.matches$.next([]);
    this.currentMatch$.next(0);
  }
}