import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { RtSearchBoxComponent } from "../rt-search-box/rt-search-box.component";
import { MatTooltipModule } from '@angular/material/tooltip';
import { SearchService } from '../../../../search/search.service';
import { hightlightModeType } from '../../../../interfaces/feed.interface';
import { AnnotsService } from '../../../../services/annots/annots.service';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'rt-search',
  standalone: true,
  imports: [ButtonComponent, IconComponent, RtSearchBoxComponent, MatTooltipModule, TranslateModule],
  templateUrl: './rt-search.component.html',
  styleUrl: './rt-search.component.scss'
})
export class RtSearchComponent implements OnInit {

  @Input() showSearchBox: boolean;
  @Output() showSearchBoxChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() disabled: boolean = false;
  @Input() visibleMarkNavModel: boolean;
  @Input() visibleMarkNavModelChange: EventEmitter<boolean>;

  @Input() visibleIssueModel: boolean;
  @Input() visibleIssueModelChange: EventEmitter<boolean>;

  @Input() indexEnabled: boolean;
  @Input() indexEnabledChange: EventEmitter<boolean>;

  @Input() hightlightMode: hightlightModeType;
  @Input() hightlightModeChange: EventEmitter<hightlightModeType>;

  constructor(private readonly searchService: SearchService, private readonly annot: AnnotsService) { }

  ngOnInit(): void {
    if (this.searchService.searchTerm) {
      this.showSearchBox = true
    }
  }

  handleShowSearchBox() {
    if (this.showSearchBox) {
      this.searchService.clear();
    }
    if (this.visibleMarkNavModel) {
      this.visibleMarkNavModel = false;
      this.visibleMarkNavModelChange.emit(this.visibleMarkNavModel);
    }

    if (this.visibleIssueModel) {
      this.visibleIssueModel = false;
      this.visibleIssueModelChange.emit(this.visibleIssueModel);
    }

    if (this.indexEnabled) {
      this.indexEnabled = false;
      this.searchService.clearIndex();
      this.indexEnabledChange.emit(this.indexEnabled);
    }

    if (this.hightlightMode) {
      this.annot.removeTemp();
      this.hightlightMode = null;
      this.hightlightModeChange.emit(this.hightlightMode);
    }

    this.showSearchBox = !this.showSearchBox;
    this.showSearchBoxChange.emit(this.showSearchBox);
  }
}
