import { Component, EventEmitter, Input, Output } from '@angular/core';
import { MatSelectModule } from '@angular/material/select';
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { SessionListItem } from '../../../../interfaces/toolbar.interface';
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { realtimeEventParams } from '../../../../interfaces/realtime.interface';
import { FormsModule } from '@angular/forms';
import { TranslateModule, TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'rt-compare',
  standalone: true,
  imports: [MatSelectModule, ButtonComponent, IconComponent, FormsModule, TranslateModule],
  templateUrl: './rt-compare.component.html',
  styleUrl: './rt-compare.component.scss'
})
export class RtCompareComponent {

  @Input() transcriptList: SessionListItem[] = []

  @Input() compareEnabled:boolean;
  @Input() compareTool: boolean;
  @Output() compareToolChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() realtimeEvent: EventEmitter<realtimeEventParams>;

  selectedSessionL: string;
  selectedSessionR: string;

  /** Unique per-instance suffix for SVG mask IDs to avoid cross-instance collisions. */
  private static instanceCounter = 0;
  readonly svgIdSuffix = `${++RtCompareComponent.instanceCounter}`;

  constructor(private readonly tost: TostbarService, private readonly translate: TranslateService) { }

  startcomapre() {
    if (!this.selectedSessionL && !this.selectedSessionR) {
      this.tost.error(this.translate.instant('rt.compare.errorSelectSession'));
      return;
    }

    this.realtimeEvent.emit({ type: 'COMPARE-MODE-ENABLED', data: { selectedSessionL: this.selectedSessionL, selectedSessionR: this.selectedSessionR } });
  }

  closeCompare(){
    this.realtimeEvent.emit({ type: 'COMPARE-MODE-CLOSED', data: { selectedSessionL: this.selectedSessionL, selectedSessionR: this.selectedSessionR } });
  }
  closeCompareTool() {
    this.compareTool = false;
    this.compareToolChange.emit(this.compareTool);
  }
}
