import { ChangeDetectionStrategy, ChangeDetectorRef, Component, effect, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges, inject } from '@angular/core';
import { NgClass } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { Subscription } from 'rxjs';
import { ToolbarService } from '../../../../services/toolbar/toolbar.service';
import { SessionListItem, toolbarEventParams } from '../../../../interfaces/toolbar.interface';
import { realtimeEventParams, sessionDetail } from '../../../../interfaces/realtime.interface';
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { FormsModule } from '@angular/forms';
import { RtToolOptionsComponent } from "../rt-tool-options/rt-tool-options.component";
import { RtSearchComponent } from "../rt-search/rt-search.component";
import { RtCompareComponent } from "../rt-compare/rt-compare.component";
import { OnlyNumberDirective } from '../../../../../shared/directive/only-number.directive';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { MatTooltipModule } from '@angular/material/tooltip';
import { hightlightModeType } from '../../../../interfaces/feed.interface';
import { SearchService } from '../../../../search/search.service';
import { AnnotsService } from '../../../../services/annots/annots.service';
import { TranslateModule } from '@ngx-translate/core';
import { SelectionActionsService } from '../../../../../shared/services/selection-actions/selection-actions.service';
import { SelectionActionsControlComponent } from '../../../../../shared/components/selection-actions/selection-actions-control.component';
import { CommunicationService } from '../../../../../shared/services/communication/communication.service';

@Component({
  selector: 'rt-toolbar',
  standalone: true,
  imports: [MatMenuModule, MatCheckboxModule, ButtonComponent, FormsModule, RtToolOptionsComponent, RtSearchComponent, RtCompareComponent, OnlyNumberDirective, MatTooltipModule, TranslateModule, NgClass, SelectionActionsControlComponent],
  templateUrl: './toolbar.component.html',
  styleUrl: './toolbar.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ToolbarComponent implements OnInit, OnChanges, OnDestroy {
  private readonly cdr = inject(ChangeDetectorRef);

  /** Subscription for REFRESH-SESSION-V2 broadcasts (fired by feed-display
   *  on the realtime 'SD' socket event — e.g. after a transcript publish).
   *  Drives a re-fetch of `sessionList` so the Draft/Live/Published pill in
   *  the day-switcher dropdown reflects the new server-side `cStatus`
   *  without forcing a full page reload. */
  private refreshSessionSub?: Subscription;

  @Input() nUserid: string;
  @Input() nCaseid: string;

  @Input() compareEnabled: boolean;

  @Input() fullViewMode: boolean;
  @Output() fullViewModeChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() visibleIssueModel: boolean;
  @Output() visibleIssueModelChange: EventEmitter<boolean> = new EventEmitter<boolean>();
  //sessions
  @Input() nSesid: string;
  @Output() nSesidChange: EventEmitter<string> = new EventEmitter<string>();
  sessionList: SessionListItem[] = [];

  transcriptList: SessionListItem[] = [];
  @Input() sessionDetail: sessionDetail;
  pageInputValue: string = '';

  @Output() toolBarEvents: EventEmitter<toolbarEventParams> = new EventEmitter<toolbarEventParams>();
  @Input() realtimeEvent: EventEmitter<realtimeEventParams>;

  compareTool: boolean;
  isLoading: boolean = true;

  /**
   * Unique suffix for SVG mask IDs inside this toolbar instance. When two
   * <feed-display> components are mounted at once (one per individual-doc tab),
   * both toolbars would otherwise define mask IDs `a` and `b` globally and the
   * second toolbar's <path mask="url(#a)"> would resolve to the first toolbar's
   * mask, producing a broken compare icon. A per-instance counter keeps the
   * references local to this toolbar.
   */
  private static instanceCounter = 0;
  readonly svgIdSuffix = `${++ToolbarComponent.instanceCounter}`;

  @Input() showTimestamp: boolean;
  @Output() showTimestampChange: EventEmitter<boolean> = new EventEmitter<boolean>();


  @Input() zoomLevel: number;
  @Output() zoomLevelChange: EventEmitter<number> = new EventEmitter<number>();


  @Input() currentPage: number;
  @Output() currentPageChange: EventEmitter<number> = new EventEmitter<number>();



  @Input() visibleMarkNavModel: boolean;
  @Output() visibleMarkNavModelChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() splitScreenEnabled: boolean;


  @Input() isSessionLive: boolean;


  @Input() indexEnabled: boolean;
  @Output() indexEnabledChange: EventEmitter<boolean> = new EventEmitter<boolean>();


  showSearchBox: boolean = false;

  @Input() hightlightMode: hightlightModeType;
  @Output() hightlightModeChange: EventEmitter<hightlightModeType> = new EventEmitter<hightlightModeType>();

  @Input() isTranscViewer: boolean;

  /** Hide MarkNav, Compare and the kebab options menu — used in the
   *  transcript-folder preview panel where those actions are not needed. */
  @Input() hideSecondaryActions: boolean = false;

  /** Render the kebab with only Zoom + Time Stamp (used by individual-doc
   *  compare mode for transcripts). Forwarded to rt-tool-options. */
  @Input() limitedActions: boolean = false;

  // ---- Mark / Copy-to-clipboard (mirrors PDF toolbar pattern) ----
  /** When true, mouseup on a feed line auto-copies selected text to clipboard. */
  isCopyToClipboard: boolean = false;
  /** Include session/doc name in the copied text (e.g., "Day-01"). */
  isCopyDocName: boolean = false;
  /** Include page.line reference in the copied text (e.g., "{4.23}"). */
  isCopyPagination: boolean = false;

  constructor(private readonly toolbarService: ToolbarService, public fds: FeedDisplayService, private readonly searchService: SearchService,
    private readonly annot: AnnotsService, public selectionActions: SelectionActionsService,
    private readonly communicationService: CommunicationService
  ) {
    // Mirror SelectionActionsService → existing 'COPY-TO-CLIP' event flow.
    // Skips first run so we don't fire on construction; only emits on user-driven changes.
    let firstRun = true;
    effect(() => {
      const state = this.selectionActions.state();
      const isCopy = this.selectionActions.isCopy();
      if (firstRun) { firstRun = false; return; }

      this.isCopyToClipboard = isCopy;
      this.isCopyDocName = state.copyDocName;
      this.isCopyPagination = state.copyPagination;

      this.toolBarEvents.emit({
        type: 'COPY-TO-CLIP',
        data: {
          copy: isCopy,
          showName: state.copyDocName,
          showPagination: state.copyPagination,
        },
      });
      this.cdr.markForCheck();
    });
  }

  async ngOnInit() {
    if (this.compareEnabled) { // || this.splitScreenEnabled
      this.isLoading = false;
      return;
    }
    this.fillPageNo();
    this.getSessionList();

    // Re-fetch the session list when the realtime 'SD' broadcast lands
    // (rebroadcast by feed-display.service as REFRESH-SESSION-V2). Without
    // this, after publishing a transcript from the Evidence folder the
    // dropdown's Draft pill stays stale until a full page reload, even
    // though the backend has already flipped cStatus to 'P'.
    this.refreshSessionSub = this.communicationService.functionCalled$.subscribe((data: any) => {
      if (data?.event === 'REFRESH-SESSION-V2') {
        this.getSessionList();
      }
    });
  }

  ngOnDestroy(): void {
    this.refreshSessionSub?.unsubscribe();
  }

  /** Timestamp of the last user-initiated page jump. While this is recent we
   *  ignore scroll-driven currentPage updates so the input does not "jump" by
   *  ±1 as the scroll tracker's most-visible-page heuristic settles. */
  private lastManualPageChangeAt: number = 0;
  private static readonly MANUAL_JUMP_LOCK_MS = 3000;

  ngOnChanges(changes: SimpleChanges): void {

    if (changes['currentPage'] && !changes['currentPage'].firstChange) {
      // Suppress scroll-driven input updates for a short window after a
      // manual "Go to Page" so the typed value (e.g. 30) does not flip to
      // 31 when onPageChangeMostVisible emits the newly-visible page.
      const recentlyManual = Date.now() - this.lastManualPageChangeAt < ToolbarComponent.MANUAL_JUMP_LOCK_MS;
      if (!recentlyManual) {
        this.fillPageNo();
      }
    }

    if (changes['visibleIssueModel'] && !changes['visibleIssueModel'].firstChange && this.visibleIssueModel) {
      this.clearSearchIfVisible();
    }

    if (changes['hightlightMode'] && !changes['hightlightMode'].firstChange && this.hightlightMode) {
      this.clearSearchIfVisible();
    }


  }

  private clearSearchIfVisible(): void {
    if (this.showSearchBox) {
      this.searchService.clear();
      this.showSearchBox = false;
    }
  }

  async getSessionList() {
    this.sessionList = await this.toolbarService.getSessionList(this.nCaseid, this.nUserid);
    // Load only transcripts for compare dropdown using cType=true
    this.transcriptList = await this.toolbarService.getSessionList(this.nCaseid, this.nUserid, 'true');
    this.isLoading = false;
    this.cdr.markForCheck();
  }

  changeSession(x: SessionListItem) {
    this.nSesid = x.nSesid;
    console.log(this.nSesid);
    this.nSesidChange.emit(this.nSesid);
  }

  openCompareTool() {

    if (this.showSearchBox) {
      this.searchService.clear();
      this.showSearchBox = false;
    }

    if (this.visibleMarkNavModel) {
      this.visibleMarkNavModel = false;
      this.visibleMarkNavModelChange.emit(this.visibleMarkNavModel);
    }

    if (this.visibleIssueModel) {
      this.visibleIssueModel = false;
      this.visibleIssueModelChange.emit(this.visibleIssueModel);
    }

    if (this.indexEnabled) {
      this.indexEnabled = false;
      this.searchService.clearIndex();
      this.indexEnabledChange.emit(this.indexEnabled);
    }

    // In individual-doc context (isTranscViewer), emit event to parent
    // to trigger compare mode like PDF does — never show rt-compare here
    if (this.isTranscViewer) {
      this.compareTool = false;
      this.toolBarEvents.emit({ type: 'COMPARE_MODE', data: true });
      return;
    }

    this.compareTool = true;
  }

  OnPageChange() {
    if (!this.pageInputValue) return;
    // Always navigate to an integer page — currentPage may be tracked as a
    // fractional page.line (e.g. 89.5 = page 89 line 5) so parseInt avoids
    // accidentally jumping to a line offset when the user types "90".
    const pg = parseInt(this.pageInputValue, 10);
    if (isNaN(pg) || pg < 1) return;
    // Start the lock window so scroll-driven currentPage updates do not
    // overwrite the typed value while the viewport is settling.
    this.lastManualPageChangeAt = Date.now();
    this.currentPage = pg;
    this.pageInputValue = String(pg);
    this.currentPageChange.emit(this.currentPage);
    this.fds.pauseEvent()
  }

  openMarkNav() {

    if (this.showSearchBox) {
      this.searchService.clear();
      this.showSearchBox = false;
    }
    if (this.visibleIssueModel) {
      this.visibleIssueModel = false;
      this.visibleIssueModelChange.emit(this.visibleIssueModel);
    }

    if (this.indexEnabled) {
      this.indexEnabled = false;
      this.searchService.clearIndex();
      this.indexEnabledChange.emit(this.indexEnabled);
    }
    if (this.hightlightMode) {
      this.annot.removeTemp();
      this.hightlightMode = null;
      this.hightlightModeChange.emit(this.hightlightMode);
    }


    this.visibleMarkNavModel = !this.visibleMarkNavModel;
    this.visibleMarkNavModelChange.emit(this.visibleMarkNavModel);

  }

  // ---- Mark / Copy-to-clipboard handlers (mirror pdf toolbar.component.ts:676-709) ----

  toggleCopyToClipboard() {
    this.isCopyToClipboard = !this.isCopyToClipboard;
    this.emitCopyState();
  }

  onCopyOptionChange(flag: 'N' | 'P', ev: any) {
    if (flag === 'N') this.isCopyDocName = ev.checked;
    if (flag === 'P') this.isCopyPagination = ev.checked;
    // Auto-activate copy mode when any checkbox is checked — user clearly
    // intends to copy if they opened the dropdown and toggled an option.
    // Deactivate only when BOTH checkboxes are unchecked.
    this.isCopyToClipboard = this.isCopyDocName || this.isCopyPagination;
    this.emitCopyState();
  }

  private emitCopyState() {
    this.toolBarEvents.emit({
      type: 'COPY-TO-CLIP',
      data: {
        copy: this.isCopyToClipboard,
        showName: this.isCopyDocName,
        showPagination: this.isCopyPagination,
      },
    });
  }

  resumePause() {
    this.fds.resumePause();
  }

  pauseEvent() {
    this.fds.pauseEvent();
  }

  handleIndex() {

    if (this.showSearchBox) {
      this.searchService.clear();
      this.showSearchBox = false;
    }

    if (this.visibleMarkNavModel) {
      this.visibleMarkNavModel = false;
      this.visibleMarkNavModelChange.emit(this.visibleMarkNavModel);
    }

    if (this.visibleIssueModel) {
      this.visibleIssueModel = false;
      this.visibleIssueModelChange.emit(this.visibleIssueModel);
    }

    if (this.hightlightMode) {
      this.annot.removeTemp();
      this.hightlightMode = null;
      this.hightlightModeChange.emit(this.hightlightMode);
    }


    this.indexEnabled = !this.indexEnabled;
    if (!this.indexEnabled) {
      this.searchService.clearIndex();
    }
    this.indexEnabledChange.emit(this.indexEnabled);
  }

  fillPageNo() {
    if (this.currentPage) {
      // currentPage can arrive as a fractional "page.line" value (e.g. 89.5)
      // — show only the integer page number so the input never displays ".5".
      this.pageInputValue = String(Math.floor(this.currentPage));
    } else {
      // currentPage === 0 signals "viewing the cover page" (not a numbered
      // transcript page). Clear the input so the placeholder is shown.
      this.pageInputValue = '';
    }
  }

  onDemoToggled() {
    this.toolBarEvents.emit({ type: 'TOGGLE-DEMO', data: null });
  }

  handleExportTranscript() {
    this.toolBarEvents.emit({ type: 'EXPORT-TRANSCRIPT', data: null });
  }
}
