import { Component, EventEmitter, OnDestroy, OnInit, Output } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { SearchMatch, SearchService } from '../../../../search/search.service';
import { Subject, Subscription, takeUntil } from 'rxjs';
import { HighlightPipe } from '../../../../pip/feed-line.pip';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { TranslateModule } from '@ngx-translate/core';

interface PageLine {
  page: number;     // 0-based page index
  line: number;     // 0-based line index within page
  start: number;    // start char index within joined line string
  end: number;      // end (exclusive)
  lineText: string;
  matchIndex?: number
}

interface Page {
  title: string;
  pg: number;
  lines: PageLine[];
  collapsed?: boolean;
}

@Component({
  selector: 'search-result',
  standalone: true,
  imports: [IconComponent, HighlightPipe, TranslateModule],
  templateUrl: './search-result.component.html',
  styleUrl: './search-result.component.scss'
})
export class SearchResultComponent implements OnInit, OnDestroy {

  @Output() hideresult: EventEmitter<number> = new EventEmitter();
  private readonly destroy$ = new Subject<void>();

  pages: Page[] = [];

  search_subscription: Subscription;
  constructor(public search: SearchService, private readonly fds: FeedDisplayService) {
    this.search_subscription = this.search.currentMatch$.subscribe((index) => {
      this.scrollToSearchMatch();
    });
  }

  hideresultr() {
    this.hideresult.emit()
  }

  ngOnInit(): void {
    this.search.matches$
      .pipe(takeUntil(this.destroy$))
      .subscribe(ms => {
        console.warn('SEARCH RESULT', ms.length)

        this.pages = this.modifySearchResult(ms);
      });
  }

  modifySearchResult(data: SearchMatch[]): Page[] {
    // 1) Deduplicate by (page, line). Keep the one with the smallest 'start'.
    data.forEach((a, index) => a.matchIndex = index);
    const dedupMap = data.reduce((map, item) => {
      const key = `${item.page}:${item.line}`;
      const existing = map.get(key);
      if (!existing || item.start < existing.start) {
        map.set(key, item);
      }
      return map;
    }, new Map<string, SearchMatch>());

    const deduped = Array.from(dedupMap.values());

    // 2) Group by page
    const grouped = deduped.reduce((acc, item) => {
      if (!acc[item.page]) {
        acc[item.page] = [];
      }
      acc[item.page].push(item);
      return acc;
    }, {} as Record<number, SearchMatch[]>);

    // 3) Sort lines inside each page
    Object.values(grouped).forEach(lines => {
      lines.sort((a, b) => (a.line - b.line) || (a.start - b.start));
    });

    // 4) Build Page[] sorted by page number
    const pages: Page[] = Object.keys(grouped)
      .map(Number)
      .sort((a, b) => a - b)
      .map(p => ({
        title: `Page ${p + 1}`,
        pg: p + 1,
        collapsed: false,
        lines: grouped[p]
      }));

    return pages;
  }

  ngOnDestroy(): void {
    if (this.search_subscription) {
      this.search_subscription.unsubscribe();
    }
    this.destroy$.next();
    this.destroy$.complete();
  }

  scrollToSearchMatch() {
    try {
      let curMatch: any = this.search.getCurrentMatch()
      if (curMatch) {
        const page = curMatch.page;
        const line: any = curMatch.line
        // this.scrollToPageLine(page, line)

        const el = document.getElementById(`search-${page}-${line}`);
        if (el) {
          el.scrollIntoView({
            behavior: 'smooth',
            block: 'start',   // align element to top of viewport
            inline: 'nearest'
          });
        }
      }

    } catch (error) {
      console.error('scrollToLastLine1', error)
    }
  }

  navigateToLine(matchIndex: number) {
    this.search.toMatch(matchIndex);
    this.fds.pauseEvent();
  }
}
